using EqlTracker.Core;
using System.Text.Json;

internal static class LivePetTests
{
    internal static void Register(Action<string,Action> test)
    {
        void Check(bool b){if(!b)throw new Exception("Live inventory / Pet evidence assertion failed");}
        var at=new DateTime(2026,10,20,10,0,0);
        CharacterProfile Profile()=>new(){Loadouts=[new(){Name="Example",Classes=["SHD","MAG","BRD"],Level=50,PetType="Earth",PetLevel=50}],SelectedLoadout="Example",CurrentExpansion="Classic",PlanThrough="Classic"};
        ItemDefinition Item(string name="Bloodmoon",string slot="PRIMARY",string cls="SHD",double damage=18)=>new(){Name=name,Key=Identity.Key(name),Classes=[cls],Slots=[slot],Stats=new(){["Damage"]=damage,["Delay"]=28},MetadataComplete=true,IntroducedExpansion="Classic"};
        InventorySnapshot Stock(params string[] names)=>new(){CapturedAt=at.AddDays(-1),Entries=names.Select((n,i)=>new InventoryEntry{Name=n,Location="General "+i,Count=1}).ToList()};
        test("Quest start parser uses explicit header fields only",()=>{var evidence=QuestStartEvidence.Parse("Example quest","! ''' Start Zone: '''\n| [[Example City]]\n|-\n! ''' Quest Giver: '''\n| [[Example NPC]]",10);Check(evidence.StartZone=="Example City"&&evidence.StartNpc=="Example NPC");Check(QuestStartEvidence.Parse("Example","Loot from a mob in [[Other Zone]]",10).StartZone=="");});
        test("Bloodmoon loot is owned, Classic and owner-class Pet eligible offline",()=>{var p=Profile();var item=Item();var c=new Catalog{Items=[item]};var inv=Stock();InventoryParser.Apply(inv,new(at,"Bloodmoon","Looted",1,"Example mob"),"log:1");Check(inv.Count(item)==1&&inv.Revision>0&&PetItemRules.ShowCandidate(item,p.ActiveLoadout,c,false));Check(GearScorer.Eligibility(item,p.ActiveLoadout,true,null,c)=="Eligible");});
        test("Standalone merge parser retains result rank without inventing loot",()=>{var parser=new LogParser("ExampleHero");var e=parser.Parse("[Tue Oct 20 10:00:00 2026] You have successfully merged two items together to create a new item: Bloodmoon +4")!.Item!;Check(e.Action=="Upgraded"&&e.Name=="Bloodmoon"&&e.Result=="Bloodmoon +4");});
        test("Unique physical merge updates rank once and keeps count",()=>{var inv=Stock("Bloodmoon");var item=new ItemObservation(at,"Bloodmoon","Upgraded",1,"","Bloodmoon +4");InventoryParser.Apply(inv,item,"log:1");InventoryParser.Apply(inv,item,"log:1");Check(inv.Entries.Single().Rank==4&&inv.Entries.Single().Count==1&&inv.RankObservations.Count==1);});
        test("Ambiguous merges retain physical ranks and record uncertainty",()=>{var inv=Stock("Bloodmoon +1","Bloodmoon +2");InventoryParser.Apply(inv,new(at,"Bloodmoon","Upgraded",1,"","Bloodmoon +3"),"log:2");Check(inv.Entries.Select(e=>e.Rank).SequenceEqual(new[]{1,2})&&inv.RankObservations.Single().Status.Contains("Unresolved"));});
        test("Merge observations cannot invent missing copies or downgrade export ranks",()=>{var inv=Stock();InventoryParser.Apply(inv,new(at,"Bloodmoon","Upgraded",1,"","Bloodmoon +3"),"log:2");Check(inv.Entries.Count==0);inv=Stock("Bloodmoon +8");InventoryParser.Apply(inv,new(at,"Bloodmoon","Upgraded",1,"","Bloodmoon +3"),"log:2");Check(inv.Entries[0].Rank==8);});
        test("Export watermark rejects old rank observations",()=>{var inv=Stock("Bloodmoon");inv.CapturedAt=at.AddHours(1);InventoryParser.Apply(inv,new(at,"Bloodmoon","Upgraded",1,"","Bloodmoon +3"),"log:2");Check(inv.Entries[0].Rank==0&&inv.RankObservations.Count==0);});
        test("Explicit candidate ranks preview owned copies but Default preserves recording",()=>{var e=new InventoryEntry{Name="Bloodmoon +17"};Check(CandidateRanks.Resolve(e,null)==17&&CandidateRanks.Resolve(e,3)==3&&CandidateRanks.Resolve(null,null)==0&&e.Rank==17);});
        test("Pet unknown restrictions remain visible without confirmed eligibility",()=>{var p=Profile();var item=Item();item.Deity="Unverified deity";Check(PetItemRules.ShowCandidate(item,p.ActiveLoadout,new(),false));Check(GearScorer.Eligibility(item,p.ActiveLoadout,true,null,new())!="Eligible");item.Deity="";item.Classes=[];Check(PetItemRules.ShowCandidate(item,p.ActiveLoadout,new(),false)&&GearScorer.Eligibility(item,p.ActiveLoadout,true,null,new()).StartsWith("Unknown"));});
        test("Class-name aliases retain owner access without allowing bows",()=>{var p=Profile();p.ActiveLoadout.Classes=["Shadow Knight","Magician","Bard"];var i=Item();Check(PetItemRules.ShowCandidate(i,p.ActiveLoadout,new(),false));i.Display.Skill="Archery";Check(!PetItemRules.ShowCandidate(i,p.ActiveLoadout,new(),false));});
        QuestDefinition Quest(string id="q",string cls="SHD")=>new(){Id=id,Name=id,Class=cls,Kind="Quest",Expansion="Classic",RewardKey="reward",Requirements=[new(){ItemKey="bloodmoon",Count=1}]};
        test("First acquired component tracks an active-class quest without queuing",()=>{var p=Profile();var c=new Catalog{Items=[Item()],Quests=[Quest()]};Check(AcquiredQuestTracking.Apply(c,p,Stock("Bloodmoon"),["Bloodmoon"])==1&&p.QuestTracking["q"]&&p.GoalQueue.Count==0);Check(AcquiredQuestTracking.Apply(c,p,Stock("Bloodmoon"))==0);});
        test("Auto tracking respects explicit untrack completion class and unknown quantities",()=>{var p=Profile();var c=new Catalog{Items=[Item()],Quests=[Quest(),Quest("other","ROG"),Quest("done")]};p.QuestTracking["q"]=false;p.CompletedQuests.Add("done");Check(AcquiredQuestTracking.Apply(c,p,Stock("Bloodmoon"))==0);p=Profile();var inv=Stock("Bloodmoon");inv.Entries[0].Count=null;Check(AcquiredQuestTracking.Apply(c,p,inv)==0);});
        test("Delayed metadata can establish component tracking",()=>{var p=Profile();var c=new Catalog{Quests=[Quest()]};Check(AcquiredQuestTracking.Apply(c,p,Stock("Bloodmoon"))==0);c.Items.Add(Item());c.InvalidateIndexes();Check(AcquiredQuestTracking.Apply(c,p,Stock("Bloodmoon"))==1);});
        test("Obtain From distinguishes inventory quest start and drop zone",()=>{var i=Item();i.Sources=[new(){Method="Drop",Mob="Example boss",Zone="Example dungeon"}];var q=Quest();q.RewardKey=i.Key;q.StartZone="Example city";q.StartNpc="Example quest giver";var rows=ItemAcquisition.For(i,new(){Quests=[q]},Stock("Bloodmoon"));Check(rows.Any(r=>r.Kind=="Inventory")&&rows.Any(r=>r.Kind=="Quest"&&r.Zone=="Example city")&&rows.Any(r=>r.Kind=="Drop"&&r.Zone=="Example dungeon"));q.StartZone="";Check(ItemAcquisition.For(i,new(){Quests=[q]},new()).Single(r=>r.Kind=="Quest").Zone=="Starting zone unknown");});
        test("Current Pet projection uses the same inferred gear without changing inventory",()=>{var p=Profile();var b=new PetBuild{PetType="Earth",PetLevel=50,Items=[new(){Id="pet-copy",ItemKey="bloodmoon",Name="Bloodmoon",Slot="Storage",Position=1,Rank=4}]};p.ActiveLoadout.ConfirmedPetInventory=b;var c=new Catalog{Items=[Item()]};var before=JsonSerializer.Serialize(b);var projected=PetEquipmentProjection.Prepare(b,p.ActiveLoadout,c);Check(projected.Items[0].Slot=="Primary"&&JsonSerializer.Serialize(b)==before);});
        test("Inventory optimization excludes components collections and nonexistent copies",()=>{var p=Profile();var item=Item();var c=new Catalog{Items=[item,new(){Name="Component",Key="component"}]};var inv=Stock("Bloodmoon +4","Component");inv.Entries.Add(new(){Name="Bloodmoon +10",Count=null,Location="Equipment"});var pool=PetEquipmentOptions.Pool(new(){PetType="Earth",PetLevel=50},p.ActiveLoadout,c,inv,PetEquipmentMode.Inventory,["Classic"]);Check(pool.Count==1&&pool[0].Rank==4&&!pool[0].Hypothetical);});
        test("Best Possible uses +10 and exact selected expansions",()=>{var p=Profile();var i=Item();var k=Item("Future blade");k.IntroducedExpansion="Kunark";var c=new Catalog{Items=[i,k]};var pool=PetEquipmentOptions.Pool(new(){PetType="Earth",PetLevel=50},p.ActiveLoadout,c,new(),PetEquipmentMode.BestPossible,["Classic"]);Check(pool.Count==1&&pool[0].Rank==10&&pool[0].Hypothetical);Check(PetEquipmentOptions.Pool(new(){PetType="Earth",PetLevel=50},p.ActiveLoadout,c,new(),PetEquipmentMode.BestPossible,[]).Count==0);});
        test("Optimization is isolated capacity-limited and does not claim global DPS",()=>{var p=Profile();var c=new Catalog{Items=[Item()]};var b=new PetBuild{PetType="Earth",PetLevel=50};var pool=PetEquipmentOptions.Pool(b,p.ActiveLoadout,c,Stock("Bloodmoon +4"),PetEquipmentMode.Inventory,["Classic"]);var before=JsonSerializer.Serialize(b);var result=PetEquipmentOptions.Optimize(b,p.ActiveLoadout,c,pool,p,CancellationToken.None);Check(result.Plan.Items.Count==1&&result.Plan.Items[0].Rank==4&&JsonSerializer.Serialize(b)==before&&result.Requirements.Count==1);});
        test("Rank efficient suggestions are capped at five and sorted by mote ranks",()=>{var p=Profile();var old=Item("Old blade",damage:15);var items=Enumerable.Range(0,8).Select(n=>Item("Blade "+n,damage:14+n)).Prepend(old).ToList();var c=new Catalog{Items=items};var b=new PetBuild{PetType="Earth",PetLevel=50,Items=[new(){Id="old",Position=1,Slot="Primary",Name=old.Name,ItemKey=old.Key}]};var pool=PetEquipmentOptions.Pool(b,p.ActiveLoadout,c,Stock(items.Skip(1).Select(i=>i.Name).ToArray()),PetEquipmentMode.Inventory,["Classic"]);var rows=PetEquipmentOptions.Upgrades(b,p.ActiveLoadout,c,p,pool,null,CancellationToken.None);Check(rows.Count<=5&&rows.Count>0&&rows.Select(r=>r.RankDelta).SequenceEqual(rows.Select(r=>r.RankDelta).Order())&&rows.All(r=>r.RequiredRank<=10));Check(PetEquipmentOptions.Upgrades(b,p.ActiveLoadout,c,p,pool,"missing",CancellationToken.None).Count==0);});
        test("Measured benchmark validates finite numbers and reconciled denominators",()=>{new PetBenchmark{Label="Example",Dps=10,Damage=100,Seconds=10}.Validate();foreach(double n in new[]{double.NaN,-1,double.PositiveInfinity}){bool bad=false;try{new PetBenchmark{Label="Example",Dps=n}.Validate();}catch(ArgumentException){bad=true;}Check(bad);}});
        List<PetComparisonResult> Compare(CharacterProfile p,PetBuild b,Catalog c)=>PetComparisonEngine.Evaluate(p,b,c,new(){Spells=[new("Earth","Earth Spell","MAG",1,"https://example.invalid",1){BasePetLevel=41,Aliases=["Earth Spell Summon"]},new("Air","Air Spell","MAG",1,"https://example.invalid",1){BasePetLevel=41}]},PetBuffCatalog.References(),[],PetEquipmentMode.IntendedSlots,CancellationToken.None);
        test("Legacy summon aliases retain recorded rank and attainable level",()=>{var p=Profile();var b=new PetBuild{PetType="Earth",PetLevel=50,SummonSpell="Earth Spell Summon",SummonClass="MAG",SummonRank=10};var rows=Compare(p,b,new());Check(rows.Single(r=>r.Pet=="Earth").Plan.PetLevel==50&&rows.Single(r=>r.Pet=="Earth").Plan.SummonRank==10&&rows.Single(r=>r.Pet=="Air").Plan.PetLevel==41);});
        test("Unconfirmed benchmarks cannot populate comparison values",()=>{var p=Profile();var b=new PetBuild{PetType="Earth"};var row=Compare(p,b,new()).First();p.PetComparison.Benchmarks.Add(new(){Label="Example",Dps=100,Hp=500,Pet=row.Pet,ContextKey=PetBenchmarks.Context(row)});Check(Compare(p,b,new()).First().DisplayDps==null);p.PetComparison.Benchmarks[0].ContextConfirmed=true;Check(Compare(p,b,new()).First().DisplayDps==100&&Compare(p,b,new()).First().Hp==500);p.PetComparison.Benchmarks[0].MechanicsVersion="old";Check(Compare(p,b,new()).First().Benchmark==null);});
        test("Benchmark contexts reject changed gear levels buffs and owner classes",()=>{var p=Profile();var b=new PetBuild{PetType="Earth",PetLevel=41};var row=Compare(p,b,new()).First();string first=PetBenchmarks.Context(row);p.ActiveLoadout.Classes=["MAG","CLR","WAR"];Check(PetBenchmarks.Context(Compare(p,b,new()).First())!=first);});
        test("Benchmarks use summed encounter duration and retain identity evidence",()=>{var p=Profile();var b=new PetBuild{PetType="Earth"};var row=Compare(p,b,new()).First(r=>r.Pet=="Earth");var sample=PetBenchmarks.FromFights(row,[new(){Id="one",PetType="Earth",PetName="ExamplePet",PetElementEvidence="Correlated Earth summon",Finished=true,PetDamage=100,Start=at,End=at.AddSeconds(10)},new(){Id="two",PetType="Earth",PetName="ExamplePet",PetElementEvidence="Correlated Earth summon",Finished=true,PetDamage=300,Start=at.AddMinutes(1),End=at.AddMinutes(1).AddSeconds(30)}],"Example",false);sample.Validate();Check(sample.Dps==10&&sample.Seconds==40&&sample.EncounterIds.Count==2&&sample.PetIdentityEvidence.Contains("Correlated"));});
        test("Comparison preference migration preserves benchmarks and physical ranks",()=>{var p=Profile();p.PetComparison.Benchmarks.Add(new(){Label="Example",Dps=100,Hp=500});var restored=EquipmentPositions.Copy(p);Check(restored.PetComparison.Benchmarks.Single().Hp==500&&restored.PetComparison.Expansions.SequenceEqual(new[]{"Classic"}));});
    }
}
